Now the sweep for tunneling. Let me implement a proper swept-AABB (moving circle vs AABB). Standard approach:

Ball moves from P0=(x0,y0) to P1=(x1,y1) over dt. Treat the ball as a point and the brick as AABB expanded by r: (bx - r, by - r, bw + 2r, bh + 2r). Then ray-box intersection of segment P0→P1 with the expanded box. Compute tEnter (earliest), tExit. If tEnter < 1 and tExit > 0 and segment overlaps in time... Standard slab method:

```
function sweptAABB(p0, p1, box, r) {
  // expand box by r
  const minX = box.x - r, maxX = box.x + box.w + r;
  const minY = box.y - r, maxY = box.y + box.h + r;
  const dirX = p1.x - p0.x, dirY = p1.y - p0.y;

  let tEnter = 0, tExit = 1;
  // X slab
  if (dirX === 0) {
    if (p0.x < minX || p0.x > maxX) return null; // parallel, outside
  } else {
    let t1 = (minX - p0.x) / dirX;
    let t2 = (maxX - p0.x) / dirX;
    if (t1 > t2) [t1, t2] = [t2, t1];
    tEnter = Math.max(tEnter, t1);
    tExit = Math.min(tExit, t2);
  }
  // Y slab
  if (dirY === 0) {
    if (p0.y < minY || p0.y > maxY) return null;
  } else {
    let t1 = (minY - p0.y) / dirY;
    let t2 = (maxY - p0.y) / dirY;
    if (t1 > t2) [t1, t2] = [t2, t1];
    tEnter = Math.max(tEnter, t1);
    tExit = Math.min(tExit, t2);
  }
  if (tEnter <= tExit && tEnter >= 0 && tEnter <= 1) {
    return { t: tEnter, exit: tExit };
  }
  return null;
}
```

