```js
// First-contact time of the ball (radius `r`, treated as a point against the
// brick grown by `r`) travelling from (x0, y0) to (x1, y1), or `null` if the
// segment never enters the brick. Continuous detection: catches the ball
// jumping over a brick between two discrete samples (level 6 + a stuttered
// frame moves 35.5 px in one step, more than a brick plus the ball).
function sweptHit(x0, y0, x1, y1, brick, r) {
  const minX = brick.x - r;
  const maxX = brick.x + brick.w + r;
  const minY = brick.y - r;
  const maxY = brick.y + brick.h + r;
  const dx = x1 - x0;
  const dy = y1 - y0;

  let tEnter = 0;
  let tExit = 1;

  if (dx === 0) {
    if (x0 < minX || x0 > maxX) return null;
  } else {
    let t1 = (minX - x0) / dx;
    let t2 = (maxX - x0) / dx;
    if (t1 > t2) {
      const tmp = t1;
      t1 = t2;
      t2 = tmp;
    }
    tEnter = Math.max(tEnter, t1);
    tExit = Math.min(tExit, t2);
    if (tEnter > tExit) return null;
  }

  if (dy === 0) {
    if (y0 < minY || y0 > maxY) return null;
  } else {
    let t1 = (minY - y0) / dy;
    let t2 = (maxY - y0) / dy;
    if (t1 > t2) {
      const tmp = t1;
      t1 = t2;
      t2 = tmp;
    }
    tEnter = Math.max(tEnter, t1);
    tExit = Math.min(tExit, t2);
    if (tEnter > tExit) return null;
  }

  if (tEnter >= 0 && tEnter <= 1 && tExit >= 0) {
    return tEnter;
  }
  return null;
}
```

