```js
// Resolves the ball against every live brick: overlap first (the face bounce),
// then a swept check for bricks the ball jumped over this step. Each hit brick
// is destroyed and scored once; the bounce itself is idempotent, so a seam
// overlapping two bricks cannot double-flip the ball.
function resolveBricks(state, x0, y0) {
  const { ball, bricks } = state;
  for (const brick of bricks) {
    if (!brick.alive) continue;

    if (collides(ball, brick)) {
      faceBounce(ball, brick);
      destroyBrick(state, brick);
      continue;
    }

    const t = sweptHit(x0, y0, ball.x, ball.y, brick, ball.r);
    if (t !== null && t > 0) {
      ball.x = x0 + (ball.x - x0) * t;
      ball.y = y0 + (ball.y - y0) * t;
      faceBounce(ball, brick);
      destroyBrick(state, brick);
    }
  }
}

function destroyBrick(state, brick) {
  brick.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(brick, state.combo);
}
```

