edits.newText:
// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit — the face resolution lives in `faceBounce` below.
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// --- Brick bounce resolution (issue #1) ------------------------------------

// Tolerance under which the two penetrations count as "equal" (a corner hit).
const CORNER_EPS = 1e-6;

// Bounces the ball off ONE brick and pushes it back out of the rectangle.
//
// The face is the axis with the SMALLER penetration: flip `vy` on a top/bottom
// hit, `vx` on a side hit, and leave the other component exactly as it was.
// Equal penetrations (within `CORNER_EPS`) mean a diagonal corner hit: both
// components flip.
//
// The flips are written with `Math.abs` so the resolution is idempotent: a
// seam (grid gap 8 px < ball diameter 14 px) overlaps two bricks in the same
// pass, and the same face applied twice must not cancel the bounce.
function faceBounce(ball, brick) {
  const overLeft = ball.x + ball.r - brick.x;
  const overRight = brick.x + brick.w - (ball.x - ball.r);
  const overTop = ball.y + ball.r - brick.y;
  const overBottom = brick.y + brick.h - (ball.y - ball.r);

  const minX = Math.min(overLeft, overRight);
  const minY = Math.min(overTop, overBottom);

  if (Math.abs(minX - minY) < CORNER_EPS) {
    // Corner: diagonal hit, both components bounce.
    if (overLeft < overRight) {
      ball.x = brick.x - ball.r;
      ball.vx = -Math.abs(ball.vx);
    } else {
      ball.x = brick.x + brick.w + ball.r;
      ball.vx = Math.abs(ball.vx);
    }
    if (overTop < overBottom) {
      ball.y = brick.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
    } else {
      ball.y = brick.y + brick.h + ball.r;
      ball.vy = Math.abs(ball.vy);
    }
    return;
  }

  if (minX < minY) {
    // Side hit: the horizontal axis bounces, the vertical one stays.
    if (overLeft < overRight) {
      ball.x = brick.x - ball.r;
      ball.vx = -Math.abs(ball.vx);
    } else {
      ball.x = brick.x + brick.w + ball.r;
      ball.vx = Math.abs(ball.vx);
    }
  } else {
    // Top/bottom hit: the vertical axis bounces, the horizontal one stays.
    if (overTop < overBottom) {
      ball.y = brick.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
    } else {
      ball.y = brick.y + brick.h + ball.r;
      ball.vy = Math.abs(ball.vy);
    }
  }
}

// First-contact time of the ball travelling from (x0, y0) to (x1, y1), or
// `null` if the segment never enters the brick. The ball (radius `r`) is
// shrunk to a point and the brick grown by `r` (Minkowski sum); a standard
// slab test then finds the earliest entry time along the segment.
//
// Continuous detection: at level 6 `ballSpeed(6)` = 710 px/s and a stuttered
// frame is capped at 50 ms, so one step moves 35.5 px — more than the 34 px
// needed to cross a brick (BRICK_H + diameter). Sampling only the positions
// before/after the move would let the ball jump over the brick untouched.
function sweptHit(x0, y0, x1, y1, brick, r) {
  const minX = brick.x - r;
  const maxX = brick.x + brick.w + r;
  const minY = brick.y - r;
  const maxY = brick.y + brick.h + r;
  const dx = x1 - x0;
  const dy = y1 - y0;

  let tEnter = 0;
  let tExit = 1;

  if (dx === 0) {
    if (x0 < minX || x0 > maxX) return null;
  } else {
    let t1 = (minX - x0) / dx;
    let t2 = (maxX - x0) / dx;
    if (t1 > t2) {
      const tmp = t1;
      t1 = t2;
      t2 = tmp;
    }
    tEnter = Math.max(tEnter, t1);
    tExit = Math.min(tExit, t2);
    if (tEnter > tExit) return null;
  }

  if (dy === 0) {
    if (y0 < minY || y0 > maxY) return null;
  } else {
    let t1 = (minY - y0) / dy;
    let t2 = (maxY - y0) / dy;
    if (t1 > t2) {
      const tmp = t1;
      t1 = t2;
      t2 = tmp;
    }
    tEnter = Math.max(tEnter, t1);
    tExit = Math.min(tExit, t2);
    if (tEnter > tExit) return null;
  }

  if (tEnter >= 0 && tEnter <= 1 && tExit >= 0) {
    return tEnter;
  }
  return null;
}

// Kills a brick and awards its points (combo included).
function destroyBrick(state, brick) {
  brick.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(brick, state.combo);
}

// Resolves the ball against every live brick for this step: overlap first
// (the face bounce), then the swept check for bricks the ball jumped over.
// Each hit brick is destroyed and scored exactly once.
function resolveBricks(state, x0, y0) {
  const { ball, bricks } = state;
  for (const brick of bricks) {
    if (!brick.alive) continue;

    if (collides(ball, brick)) {
      faceBounce(ball, brick);
      destroyBrick(state, brick);
      continue;
    }

    const t = sweptHit(x0, y0, ball.x, ball.y, brick, ball.r);
    if (t !== null && t > 0) {
      ball.x = x0 + (ball.x - x0) * t;
      ball.y = y0 + (ball.y - y0) * t;
      faceBounce(ball, brick);
      destroyBrick(state, brick);
    }
  }
}

