+// Brick collisions (issue #1). The fixtures mirror sonde.test.js but drive
+// `step()` directly, where the resolution now lives.
+
+// Fresh brick per test: `step()` mutates the bricks it destroys.
+const makeBrick = (over = {}) => ({
+  x: 100,
+  y: 100,
+  w: BRICK_W,
+  h: BRICK_H,
+  row: 0,
+  alive: true,
+  points: 10,
+  ...over,
+});
+
+// A ball already overlapping a brick is resolved without any movement (dt = 0),
+// so these tests judge the resolution, not the integration.
+
+test('step: side hit flips vx and leaves vy alone', () => {
+  const state = createState(1);
+  state.bricks = [makeBrick()];
+  state.ball = { x: 96, y: 110, r: BALL_R, vx: 300, vy: 30 };
+  step(state, 0);
+  assert.ok(state.ball.vx < 0, 'vx should flip on a left-face hit');
+  assert.equal(state.ball.vy, 30, 'vy must stay untouched');
+});
+
+test('step: top/bottom hit flips vy and leaves vx alone', () => {
+  const state = createState(1);
+  state.bricks = [makeBrick()];
+  state.ball = { x: 136, y: 124, r: BALL_R, vx: 30, vy: -300 };
+  step(state, 0);
+  assert.ok(state.ball.vy > 0, 'vy should flip on a bottom-face hit');
+  assert.equal(state.ball.vx, 30, 'vx must stay untouched');
+});
+
+test('step: corner hit flips both components', () => {
+  const state = createState(1);
+  state.bricks = [makeBrick()];
+  state.ball = { x: 96, y: 96, r: BALL_R, vx: 300, vy: 300 };
+  step(state, 0);
+  assert.ok(state.ball.vx < 0, 'vx should flip on a corner hit');
+  assert.ok(state.ball.vy < 0, 'vy should flip on a corner hit');
+});
+
+test('step: the ball is pushed back out of the brick', () => {
+  const state = createState(1);
+  state.bricks = [makeBrick()];
+  state.ball = { x: 96, y: 110, r: BALL_R, vx: 300, vy: 30 };
+  step(state, 0);
+  assert.equal(state.ball.x + state.ball.r, 100, 'right edge flush with the brick left edge');
+  assert.equal(state.bricks[0].alive, false, 'the brick is destroyed');
+});
+
+test('step: a seam overlapping two bricks bounces exactly once', () => {
+  const state = createState(1);
+  state.bricks = [makeBrick(), makeBrick({ x: 100 + BRICK_W + BRICK_GAP })];
+  state.ball = { x: 176, y: 126, r: BALL_R, vx: 6, vy: -60 };
+  step(state, 0);
+  assert.ok(state.ball.vy > 0, 'vy must flip exactly once');
+  assert.equal(state.ball.vx, 6, 'vx must stay untouched');
+});
+
+test('step: a fast ball sweeps through a brick instead of tunnelling', () => {
